const { body, headers } = $input.first().json;
const part = Number(headers['x-whatsapp-forwarder-part'] ?? 1);
if (!body || !Number.isSafeInteger(part) || part < 1 || typeof body.text !== 'string' || typeof body.sender !== 'string') {
  throw new Error('Invalid forwarder payload');
}

const sender = Array.from(body.sender).slice(0, 128).join('');
const group = typeof body.group === 'string' ? Array.from(body.group).slice(0, 128).join('') : '';
const title = group ? `${group} · ${sender}` : sender;
const attachment = body.attachment ? `[${body.attachment}]` : '';
const bodyText = attachment ? (body.text ? `${attachment} ${body.text}` : attachment) : body.text;
if (!bodyText.trim()) throw new Error('Message has no content');

const limit = 4096;
let parts = [bodyText];
if (`${title}: ${bodyText}`.length > limit) {
  // Count UTF-16 code units conservatively, without breaking surrogate pairs.
  // Reserve space for the sender and multipart numbering on every part.
  const contentLimit = limit - title.length - 32;
  parts = [];
  let chunk = '';
  for (const character of bodyText) {
    if (chunk.length + character.length > contentLimit) {
      parts.push(chunk);
      chunk = '';
    }
    chunk += character;
  }
  if (chunk) parts.push(chunk);
}
if (part > parts.length) throw new Error('Invalid multipart cursor');

const numberedTitle = parts.length > 1 ? `${title} (${part}/${parts.length})` : title;
const text = `${numberedTitle}: ${parts[part - 1]}`
  .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
return [{ json: {
  text,
  silent: part > 1,
  nextPart: part < parts.length ? part + 1 : 0,
} }];
